import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Ignored Test Inventory and Triage","description":"","frontmatter":{"title":"Ignored Test Inventory and Triage","type":"adr","date":"2026-08-29T00:00:00.000Z","status":"accepted","status_note":"Accepted"},"headers":[],"relativePath":"handl/project/adrs/0038-ignored-test-inventory-and-triage.md","filePath":"vendored/handl/project/adrs/0038-ignored-test-inventory-and-triage.md"}`),a={name:`handl/project/adrs/0038-ignored-test-inventory-and-triage.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0038-ignored-test-inventory-and-triage" tabindex="-1">ADR-0038: Ignored Test Inventory and Triage <a class="header-anchor" href="#adr-0038-ignored-test-inventory-and-triage" aria-label="Permalink to “ADR-0038: Ignored Test Inventory and Triage”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><h3 id="keep-all-34-ignored-tests" tabindex="-1">Keep all 34 ignored tests <a class="header-anchor" href="#keep-all-34-ignored-tests" aria-label="Permalink to “Keep all 34 ignored tests”">​</a></h3><p>None of the ignored tests are removed. Each test is an executable specification for a planned feature. Removing them would lose the contract and force re-derivation of the expected behavior when the feature is implemented.</p><h3 id="classify-by-resolution-path" tabindex="-1">Classify by resolution path <a class="header-anchor" href="#classify-by-resolution-path" aria-label="Permalink to “Classify by resolution path”">​</a></h3><p>Each workstream has a clear unblock condition:</p><table tabindex="0"><thead><tr><th>#</th><th>Workstream</th><th>Tests</th><th>Unblock condition</th><th>Depends on</th></tr></thead><tbody><tr><td>1</td><td>VM eval</td><td>11</td><td>Implement <code>CanonicalVm::eval</code> tree-walking interpreter</td><td>—</td></tr><tr><td>2</td><td>LSP plugins</td><td>6</td><td>Wire <code>ToolingHost</code> to invoke LSP capabilities with parsed AST</td><td>Parser (done)</td></tr><tr><td>3</td><td>Format/diagnostics</td><td>4</td><td>Wire <code>ToolingHost::format</code> and <code>diagnose</code> to invoke platform capabilities</td><td>Formatter (done), Linter (done)</td></tr><tr><td>4</td><td>Network/TLS</td><td>5</td><td>Add <code>tls</code> feature flag or move to CI-only suite</td><td>—</td></tr><tr><td>5</td><td>Concurrent stress</td><td>5</td><td>Fix scheduler race; gate behind <code>stress</code> feature flag</td><td>—</td></tr><tr><td>6</td><td>HTTP server function values</td><td>2</td><td>Wire <code>route_function</code> to VM eval pipeline</td><td>Workstream 1</td></tr><tr><td>7</td><td>Loader/CLI</td><td>1</td><td>Expose <code>load</code> capability through <code>ToolingHost</code></td><td>—</td></tr></tbody></table><h3 id="priority-order-for-un-ignoring" tabindex="-1">Priority order for un-ignoring <a class="header-anchor" href="#priority-order-for-un-ignoring" aria-label="Permalink to “Priority order for un-ignoring”">​</a></h3><ol><li><p><strong>Workstream 3 (format/diagnostics)</strong> — the formatter and linter pipelines are already implemented and registered in <code>kit-canonical</code>. The only missing piece is <code>ToolingHost</code> calling the <code>format</code> and <code>lint</code> capabilities. This is the lowest-effort, highest-value unblock.</p></li><li><p><strong>Workstream 2 (LSP plugins)</strong> — the LSP plugins are implemented and registered. <code>ToolingHost</code> needs to parse the source, then invoke <code>completion</code>, <code>goto-def</code>, and <code>document-symbols</code> capabilities with the AST and position. Depends on the parser, which is complete.</p></li><li><p><strong>Workstream 1 (VM eval)</strong> — the largest workstream. Unblocks workstream 6 as a side effect. Requires implementing the tree-walking interpreter in <code>plugin-vm-backend-rust-interpreter</code>.</p></li><li><p><strong>Workstream 7 (loader/CLI)</strong> — small effort once <code>ToolingHost</code> exposes a <code>load</code> entry point.</p></li><li><p><strong>Workstream 4 (network/TLS)</strong> — move behind a <code>tls</code> feature flag so they don&#39;t run by default. No implementation work needed, just gating.</p></li><li><p><strong>Workstream 5 (concurrent stress)</strong> — gate behind a <code>stress</code> feature flag. Fix the scheduler race separately.</p></li><li><p><strong>Workstream 6 (HTTP server function values)</strong> — unblocked once workstream 1 is done.</p></li></ol><h3 id="no-feature-flags-for-workstreams-1–3-and-7" tabindex="-1">No feature flags for workstreams 1–3 and 7 <a class="header-anchor" href="#no-feature-flags-for-workstreams-1–3-and-7" aria-label="Permalink to “No feature flags for workstreams 1–3 and 7”">​</a></h3><p>Workstreams 1, 2, 3, and 7 are core platform features. Their tests should run by default once un-ignored. No feature flag is needed.</p><h3 id="feature-flags-for-workstreams-4-and-5" tabindex="-1">Feature flags for workstreams 4 and 5 <a class="header-anchor" href="#feature-flags-for-workstreams-4-and-5" aria-label="Permalink to “Feature flags for workstreams 4 and 5”">​</a></h3><p>Network/TLS integration tests and concurrent stress tests do not belong in the default <code>cargo test</code> run even when passing. They will be gated behind <code>tls</code> and <code>stress</code> feature flags respectively, and the <code>#[ignore]</code> attribute will be replaced by <code>#[cfg(feature = &quot;...&quot;)]</code>.</p><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>The workspace currently has 34 ignored tests across 10 files in 7 distinct workstreams. These tests were written ahead of their implementing code — they describe expected behavior for features that are stubbed, unwired, or require external infrastructure. The <code>#[ignore]</code> attribute keeps them out of the default <code>cargo test</code> run while preserving them as executable specifications.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li>none recorded — legacy record; the design doc lists what was deferred.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>All 34 ignored tests remain in the codebase as executable specifications.</li><li>The unblock condition for each workstream is explicit and tracked in this ADR.</li><li>Workstreams 4 and 5 will eventually move from <code>#[ignore]</code> to <code>#[cfg(feature)]</code>.</li><li>Workstreams 1, 2, 3, 6, and 7 will have <code>#[ignore]</code> removed when their unblock condition is met.</li><li>This ADR should be updated when a workstream is unblocked, recording the commit that un-ignored the tests.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li>Code and tests are named in the design doc.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>The full record (context, tables, phases, trade-offs): <a href="./../design/0038-ignored-test-inventory-and-triage.html"><code>design/0038-ignored-test-inventory-and-triage.md</code></a>.</p>`,23)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};